/** Builds the exact multipart request for one intent; a retry of that intent rebuilds identical bytes. */
export function importUploadRequest(file: File, operationId: string, expectedRevision: number): { headers: Record<string, string>; body: Blob } {
  const boundary = `FinitudeImport-${operationId}`;
  const filename = encodeURIComponent(file.name).replace(/['()*]/g, character => `%${character.charCodeAt(0).toString(16)}`);
  return {
    headers: { 'Idempotency-Key': operationId, 'If-Match': String(expectedRevision), 'Content-Type': `multipart/form-data; boundary=${boundary}` },
    body: new Blob([`--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="upload"; filename*=UTF-8''${filename}\r\nContent-Type: ${mediaType(file)}\r\n\r\n`, file, `\r\n--${boundary}--\r\n`])
  };
}
