/** One queue per import survives navigation and view changes, never an account or permission change. */
export function importUploadQueue(importId: string, guard: AdminGuard = adminWorkspace.capture()): ImportUploadQueue {
  const key = `upload-queue:${importId}`, found = adminWorkspace.buffer<ImportUploadQueue>(key);
  if (found) return found;
  const queue = new ImportUploadQueue(importId, guard); adminWorkspace.retain(key, queue, guard); return queue;
}
